        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t s = 0.0f;
            Index_type j = 0;

            while (j < coefflen) {
                size_t vl = __riscv_vsetvl_e32m1(coefflen - j);

                vfloat32m1_t vcoeff = __riscv_vle32_v_f32m1(&apps_coeff[j], vl);
                vfloat32m1_t vin = __riscv_vle32_v_f32m1(&apps_in[i + j], vl);
                vfloat32m1_t vprod = __riscv_vfmul_vv_f32m1(vcoeff, vin, vl);

                vfloat32m1_t vsum = __riscv_vfredosum_vs_f32m1_f32m1(vprod, __riscv_vfmv_v_f_f32m1(0.0f, vl), vl);
                s += __riscv_vfmv_f_s_f32m1_f32(vsum);

                j += vl;
            }

            apps_out[i] = s;
        }
        dummy(apps_out, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

