real_t apps_ltimes_noview(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type num_d = LTIMES_NUM_D, num_m = LTIMES_NUM_M;
    Index_type num_g = LTIMES_NUM_G, num_z = LTIMES_NUM_Z;

    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type z = 0; z < num_z; ++z) {
            for (Index_type g = 0; g < num_g; ++g) {
                for (Index_type m = 0; m < num_m; ++m) {
                    Index_type phidat_idx = m + g * num_m + z * num_m * num_g;
                    Index_type psidat_base = g * num_d + z * num_d * num_g;

                    real_t acc = lt_phidat[phidat_idx];
                    Index_type dd = 0;

                    for (; dd + 3 < num_d; dd += 4) {
                        size_t vl = __riscv_vsetvl_e64m1(4);

                        vfloat64m1_t v_elldat = __riscv_vle64_v_f64m1(
                            (const double *)(&lt_elldat[dd + m * num_d]), vl);
                        vfloat64m1_t v_psidat = __riscv_vle64_v_f64m1(
                            (const double *)(&lt_psidat[dd + psidat_base]), vl);
                        vfloat64m1_t v_acc = __riscv_vfmv_v_f_f64m1(acc, vl);

                        v_acc = __riscv_vfmacc_vv_f64m1(v_acc, v_elldat, v_psidat, vl);
                        acc = __riscv_vfmv_f_s_f64m1_f64(v_acc);
                    }

                    for (; dd < num_d; ++dd) {
                        acc += lt_elldat[dd + m * num_d] *
                               lt_psidat[dd + psidat_base];
                    }

                    lt_phidat[phidat_idx] = acc;
                }
            }
        }
        dummy(lt_phidat, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

