real_t apps_pressure(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t cls = 1.0f, p_cut = 1.0e-7f, pmin = 0.0f, eosvmax = 1.0e9f;
    const int outer = iterations / 4 + 1;

    for (int nl = 0; nl < outer; nl++) {
        Index_type i = 0;
        for (; i < APPS_N1D; ++i) {
            apps_bvc[i] = cls * (apps_compression[i] + 1.0f);
        }

        i = 0;
        for (; i < APPS_N1D; ++i) {
            real_t p = apps_bvc[i] * apps_e_old[i];
            if (ABS(p) < p_cut)         p = 0.0f;
            if (apps_vnewc[i] >= eosvmax) p = 0.0f;
            if (p < pmin)               p = pmin;
            apps_p_new[i] = p;
        }

        dummy(apps_p_new, apps_bvc, NULL, NULL, NULL, p_cut);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

